export const TEMPLATE_STEERING_MD: string = "# CHIMERA // LAB (`neuro-chimera-synth`) — Template Steering\n\n- **Mode:** Mode A native website inside GenUI Studio, previewed at `/preview/neuro-chimera-synth`.\n- **Spec:** `.kiro/specs/neuro-chimera-synth/` (`requirements.md`, `design.md`, `tasks.md`).\n- **Scoped rules:** `.kiro/steering/chimera-frankenstein-rules.md`.\n- **State:** `components/lab-store.ts` owns the live `PhysarumNetwork` and the lab UI state. Components read it through `useLab` and change it only through the store's actions.\n- **Engine:** `lib/chimera/` is pure: SQL parser, cost planner, Physarum solver, scenarios, benchmarks, cron preview and the sonification mapping. No `Date`, `Math.random`, `eval` or network calls.\n- **Rendering:** one 2D canvas and one `requestAnimationFrame` loop for the network, with preallocated buffers. The solver steps on a timer (at most 10 store publishes per second), never inside the render loop.\n- **Visuals:** bioluminescent palette only (`#020A0E #00F5B8 #FFB000 #FF2A6D`, quartz panels `rgba(2, 18, 24, 0.78)` with `1px solid rgba(0, 245, 184, 0.25)` borders). Every colour state also has a label or icon. Pulses stay under 3 per second and stop under reduced motion.\n- **Safety:** streamed props are Zod validated and healed. Chemotaxis packets with unknown nodes, invalid strengths or unparsable SQL are quarantined. No raw HTML or `eval`.\n";

export const TEMPLATE_SKILL_MD: string = "---\nname: neuro-chimera-synth\ndescription: Use when building, extending or remixing the CHIMERA // LAB template, a Physarum slime-mould simulation of database query traffic with a deterministic SQL parser and planner, local SQL optimizer agents and telemetry sonification.\n---\n\n# CHIMERA // LAB Skill\n\n## What this template is\nA live network of services and databases where query traffic flows like a slime mould. Full-table scans and N+1 loops show up as crimson tubes and pulsing nodes. Operators and three deterministic optimizer agents fix them with composite indexes and batched rewrites, and the network re-routes. A landing-page mode presents the same engine as an AI research SaaS.\n\n## Key modules\n- `lib/chimera/sql-parser.ts`: `parseSql`, `printSql`, `SqlParseError` (with offsets). Bounded by `MAX_SQL_LENGTH`, `MAX_SQL_TOKENS` and `MAX_EXPR_DEPTH`.\n- `lib/chimera/query-planner.ts`: `planQuery`, `explainPlan`, `recommendIndexes`, `withIndex`, `indexDdl`.\n- `lib/chimera/bio-solver.ts`: `PhysarumNetwork` with `step`, `severNode`, `reviveNode`, `moveNode`, `injectIndex`, `rewriteNPlusOne`, `setQuerySql`, `applyChemotaxisPulse`, `runOptimizerAgent`.\n- `lib/chimera/scenarios.ts`: seven scenarios, from an unindexed checkout spike to a genomics pipeline.\n- `lib/chimera/compare.ts`: before/after plan comparison for the SQL deck.\n- `lib/chimera/sonifier.ts`: pure `mapTelemetryToSound` and `predictPartials`, plus the Web Audio engine.\n- `components/`: `ChimeraLabShell` (root), `BioNetworkCanvas`, `SqlAstExecutionCompare`, `OptimizerAgentConstellation`, `SonificationSpectrumHUD`, `BiotechHeroSection`, `InteractiveBenchmarkBento`, `PricingTiersSection`, `ChemotaxisPacket`.\n\n## Local optimizer agents\n| Agent | Lab action | Previewed audit cadence |\n| --- | --- | --- |\n| `chimera-architect` | Full audit: top indexes plus N+1 batching | `0 */6 * * *` |\n| `index-surgeon` | Best index for the target node's dataset | `0 3 * * *` |\n| `deadlock-hunter` | Batches N+1 loops, reports timeouts and saturated nodes | `*/30 * * * *` |\n\n## Rules for changes\n1. Keep `lib/chimera/` pure and deterministic. Same SQL and statistics give the same plan and EXPLAIN text.\n2. Add scenarios to `CHIMERA_SCENARIOS`; the catalog's `scenarioId` enum and the benchmark matrix pick them up.\n3. Stay inside the bioluminescent palette and pair every colour with a label or icon.\n4. Benchmark and latency figures are simulator estimates. Never present them as measurements.\n\n## Install\n```bash\nnpx genui-studio add neuro-chimera-synth\n```\n";

export const TEMPLATE_KIRO_POWER_MD: string = "---\nname: \"neuro-chimera-synth\"\ndisplayName: \"CHIMERA // LAB — Bio-Digital SQL Synthesizer & Optimizer Lab\"\ndescription: \"Physarum slime-mould simulation of database query traffic with a deterministic SQL parser and cost planner, before/after EXPLAIN comparison, three local SQL optimizer agents, and telemetry sonification.\"\nkeywords: [\"postgres\", \"sql\", \"query-planner\", \"explain\", \"indexes\", \"n+1\", \"physarum\", \"web-audio\"]\n---\n\n# CHIMERA // LAB Kiro Power\n\n## Onboarding\n1. Install the template: `npx genui-studio add neuro-chimera-synth`.\n2. Read `.kiro/specs/neuro-chimera-synth/design.md` for the solver, planner and sonification models.\n3. Steering for this directory lives in `.kiro/steering/chimera-frankenstein-rules.md`.\n\n## Common tasks\n- **Add a scenario:** append a `ScenarioSpec` to `CHIMERA_SCENARIOS` in `lib/chimera/scenarios.ts`, then run the property tests.\n- **Support more SQL:** extend the parser and printer together, then the planner. Unsupported syntax must keep throwing `SqlParseError`.\n- **Customize optimizer agents:** edit `OPTIMIZER_AGENTS` in `components/OptimizerAgentConstellation.tsx` and dispatch rules in `components/lab-store.ts`.\n- **Verify:** `pnpm --filter @genui-studio/templates exec vitest run src/__tests__/chimera-lab.pbt.test.ts`.\n\n## Guarantees\n- The solver never produces NaN or infinite values; unreachable queries are reported as failed.\n- Adding a recommended index never raises a query's planned cost.\n- Corrupted or cyclic streamed packets are healed or quarantined without crashing the page.\n- Audio starts only after a user gesture and can be muted.\n";

